SELECT d.entity_kind || ' ' || coalesce(nullif(d.entity_name, ''), '(одиночный)') || ' — снятый термин ' || t.term || ' употреблён: «' || left(trim(l.line), 70) || '»' AS detail FROM term_retired t JOIN project_documents d ON d.project_id = t.project_id CROSS JOIN LATERAL regexp_split_to_table(d.content, E'\n') AS l(line) WHERE t.project_id = $1 AND regexp_replace(regexp_replace(l.line, '~~[^~]*~~', '', 'g'), '\[[^]]*\]\(https?://[^)]*\)', '', 'g') ~ ('(^|[^`[:alnum:]_])' || regexp_replace(t.term, '([.*+?^${}()|\[\]\\])', '\\\1', 'g') || '([^`[:alnum:]_]|$)') AND NOT EXISTS (SELECT 1 FROM scheme($1) h WHERE h.role IN ('term.retirement-home','term.foreign-home') AND h.value = d.entity_kind) ORDER BY 1
